fn twice(mut callback: impl FnMut()) {
    callback();
    callback();
}
fn main() {
    let mut count = 0;
    { twice(|| count += 1); }
    assert_eq!(count, 2);
    let text = String::from("crab");
    let read = move || text.len();
    assert_eq!(read(), 4);
    assert_eq!(read(), 4);
}

